package com.intro;//package

public class Byte1 {
//class
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
       byte b1 = 123;
       byte b2 = (byte)129;
       
       System.out.println(b2);
       
       
       System.out.println("Byte operations");
       System.out.println();
       System.out.println("Addition is : "+(b1+b2));
       System.out.println("Substraction is :"+(b1-b2));
       System.out.println("Multiplication is :"+(b1 * b2));
       System.out.println("Division is :"+(b1/b2));
       
       System.out.println();
       
       System.out.println("Short operations");
       System.out.println();
       short s1 = 3450;
       short s2 = -345;
       
       System.out.println("Addition is : "+(s1+s2));
       System.out.println("Substraction is :"+(s1-s2));
       System.out.println("Multiplication is :"+(s1 * s2));
       System.out.println("Division is :"+(s1/s2));
       
       int i1 = 3534500;
       int i2 = -500;
       
       System.out.println();
       System.out.println("Int operations");
       System.out.println();
       System.out.println("Addition is : "+(i1+i2));
       System.out.println("Substraction is :"+(i1-i2));
       System.out.println("Multiplication is :"+(i1 * i2));
       System.out.println("Division is :"+(i1/i2));
       
       
       
	}

}
